#!/usr/bin/env bash
# Regression test for tests/check_gate_wiring.sh. The gate's value is the pair it
# can prove — a name present in the Linux gate's step list and in the Windows
# gate's — so each half needs its own boundary: a name present once must still be
# red, and an empty tree must read as not applicable rather than a vacuous pass.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  gate-wiring self-test (no git checkout)\n'
    exit 125
}
check=$root/tests/check_gate_wiring.sh
if [ ! -f "$check" ]; then
    printf 'FAIL  %s is missing\n' "$check"
    exit 1
fi

# Not a bare /tmp: MSYS child shells default TMP/TEMP to /tmp while native
# git.exe maps a /tmp argument to C:\tmp.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE")
else
    tmpbase=${TMP:-.}
fi
tmp=$(mktemp -d "$tmpbase/pime-gate-wiring-selftest.XXXXXX")
sandbox=$tmp/repo
mkdir -p "$sandbox/tests"

cleanup() {
    rm -rf "$tmp"
}
trap cleanup EXIT

git -C "$sandbox" init -q >/dev/null

failures=0

expect() {
    local want="$1" name="$2" out got
    out=$(cd "$sandbox" && bash "$check" 2>&1)
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s (rc %s, want %s)\n%s\n' "$name" "$got" "$want" "$out"
        failures=$((failures + 1))
    fi
}

expect_named() {
    local want="$1" name="$2" needle="$3" out got
    out=$(cd "$sandbox" && bash "$check" 2>&1)
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s (rc %s, want %s)\n%s\n' "$name" "$got" "$want" "$out"
        failures=$((failures + 1))
        return
    fi
    case "$out" in
        *"$needle"*) : ;;
        *) printf 'FAIL  %s: output does not name %s\n%s\n' "$name" "$needle" "$out"
           failures=$((failures + 1)) ;;
    esac
}

reset_index() {
    local f
    for f in $(git -C "$sandbox" ls-files); do
        rm -f "$sandbox/$f"
    done
    git -C "$sandbox" rm -q -r --cached . >/dev/null 2>&1 || true
}

gate_pair() {
    printf '%s\n' "step 'x' \"\$ROOT/tests/check_one.sh\"" > "$sandbox/tests/run_local_tests.sh"
    printf '%s\n' "run_native 'x' 'bash.exe tests/check_one.sh'" > "$sandbox/tests/verify_windows.sh"
}

# Both gates name the script: the pair the gate exists to prove.
reset_index
gate_pair
printf '#!/usr/bin/env bash\n' > "$sandbox/tests/check_one.sh"
git -C "$sandbox" add tests/run_local_tests.sh tests/verify_windows.sh tests/check_one.sh
expect 0 'a script named by both gates is wired'

# Named by the Linux gate only: still red, and the Windows line is the one named.
reset_index
printf '%s\n' "step 'x' \"\$ROOT/tests/check_one.sh\"" > "$sandbox/tests/run_local_tests.sh"
printf '%s\n' "run_native 'y' 'bash.exe tests/check_other.sh'" > "$sandbox/tests/verify_windows.sh"
printf '#!/usr/bin/env bash\n' > "$sandbox/tests/check_one.sh"
printf '#!/usr/bin/env bash\n' > "$sandbox/tests/check_other.sh"
git -C "$sandbox" add tests/run_local_tests.sh tests/verify_windows.sh \
    tests/check_one.sh tests/check_other.sh
expect_named 1 'a name present once is unwired in the other gate' \
    'unwired in tests/verify_windows.sh: tests/check_one.sh'
expect_named 1 'the missing Linux side is named too' \
    'unwired in tests/run_local_tests.sh: tests/check_other.sh'

# A self-test is a script like any other: it needs its own step.
reset_index
gate_pair
printf '%s\n' >> "$sandbox/tests/run_local_tests.sh"
printf "step 'x' \"\$ROOT/tests/check_one_test.sh\"\n" >> "$sandbox/tests/run_local_tests.sh"
printf '#!/usr/bin/env bash\n' > "$sandbox/tests/check_one.sh"
printf '#!/usr/bin/env bash\n' > "$sandbox/tests/check_one_test.sh"
git -C "$sandbox" add tests/run_local_tests.sh tests/verify_windows.sh \
    tests/check_one.sh tests/check_one_test.sh
expect_named 1 'an unwired self-test is reported' \
    'unwired in tests/verify_windows.sh: tests/check_one_test.sh'

# No check script at all is not applicable rather than a vacuous pass.
reset_index
gate_pair
git -C "$sandbox" add tests/run_local_tests.sh tests/verify_windows.sh
expect 125 'a tree without check scripts is not applicable'

# A missing gate file is not applicable either: the pair is the contract.
reset_index
printf '#!/usr/bin/env bash\n' > "$sandbox/tests/check_one.sh"
git -C "$sandbox" add tests/check_one.sh
expect 125 'a missing gate file is not applicable'

# Outside a git checkout the gate is not applicable, not a failure.
nowork=$tmp/nowork
mkdir -p "$nowork"
out=$(cd "$nowork" && bash "$check" 2>&1)
got=$?
if [ "$got" -ne 125 ]; then
    printf 'FAIL  outside a checkout (rc %s, want 125)\n%s\n' "$got" "$out"
    failures=$((failures + 1))
fi

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
